/* Provenance: written clean-room from the psx-spx documentation and black-box vectors of the original code, with no SDK or
 * third-party decoder source.
 * Standalone checker: resumable/bounded API of the clean-room STR/BS VLC decoder (pe_vlc_decode.c)
 * against the bound/resume call chains of the original (black box).
 *   cc -std=c99 -Wall -Wextra -Werror -Ipc_port/include -Ipc_port/tests pc_port/tools/pe_mdec_vlc_bound_check.c pc_port/platform/pe_vlc_decode.c -o bound_check
 *   PE_DISC1_BIN=<Disc 1 .bin> ./bound_check
 * Vectors: pc_port/tests/retail_mdec_vlc_bound_cases.h (generated by pc_port/tools/pe_mdec_vlc_bound_vectors.py) for the
 * frames of retail_mdec_vlc_cases.h (synthetic) and, through PE_DISC1_BIN, three real frames (disc order index = real_index-1).
 * Each chain is replayed as the movie code calls the original: step 0 = pe_vlc_decode_begin + step with the case's bound,
 * later steps = resume steps (only after a bounded exit), every step with the case's bound.  Per step compared:
 *   returned value, bytes added to the output stream (4 header bytes in the first call + 2 per halfword, FNV-1a64 of them),
 *   the returned input pointer relative to the frame (8 + 2*ceil((end_bits+7)/16)) and the returned output pointer
 *   relative to the first arena (4 + 2*halfwords so far).  Informational: the end word (4 + 4*count) as the adapter will derive it.
 * A step on which the original never exits within its instruction budget (ret 0xFFFFFFFF) must give a negative return here.
 * Exit 0 = every step explained (matched, or listed as a known out-of-spec divergence).  pe_mdec_vlc_bound_check.sh adds mutants. */
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "pe_vlc_decode.h"
#include "retail_mdec_vlc_cases.h"
#include "retail_mdec_vlc_bound_cases.h"

#define NCASES (sizeof(MDECVLCB_case) / sizeof(MDECVLCB_case[0]))
#define NSTEPS (sizeof(MDECVLCB_step) / sizeof(MDECVLCB_step[0]))
#define HWCAP (1u << 19)

static uint64_t Fnv(const uint8_t *p, size_t n, uint64_t h)
{
    while (n--) { h ^= *p++; h *= UINT64_C(1099511628211); }
    return h;
}
#define FNV0 UINT64_C(14695981039346656037)

/* ---- real frames: disc scan identical to the vector generator's frames_on_disc() ---- */
typedef struct { uint32_t first, last, size; } Fr;
static int ReadSector(FILE *f, uint32_t lba, uint8_t raw[2352])
{
    return fseek(f, (long)lba * 2352L, SEEK_SET) == 0 && fread(raw, 1, 2352, f) == 2352;
}
static Fr *ScanFrames(FILE *f, unsigned need)
{
    Fr *out = calloc(need, sizeof *out);
    unsigned n = 0;
    uint32_t lba = 0, cfirst = 0, cframe = 0, csize = 0, csecs = 0;
    int cur = 0;
    uint8_t raw[2352];
    if (!out) return NULL;
    rewind(f);
    while (n < need && fread(raw, 1, 2352, f) == 2352) {
        if (!(raw[18] & 8u) || raw[24] != 0x60 || raw[25] != 1 || raw[26] != 1 || raw[27] != 0x80) { lba++; continue; }
        {
            unsigned index = raw[28] | (raw[29] << 8), total = raw[30] | (raw[31] << 8);
            uint32_t frame_no = raw[32] | (raw[33] << 8) | (raw[34] << 16) | ((uint32_t)raw[35] << 24);
            uint32_t size = raw[36] | (raw[37] << 8) | (raw[38] << 16) | ((uint32_t)raw[39] << 24);
            if (index == 0) { cur = 1; cfirst = lba; cframe = frame_no; csize = size; csecs = 1; }
            else if (cur && index == csecs && frame_no == cframe) csecs++;
            else { cur = 0; lba++; continue; }
            if (cur && index == total - 1u) { out[n].first = cfirst; out[n].last = lba; out[n].size = csize; n++; cur = 0; }
        }
        lba++;
    }
    return n == need ? out : (free(out), NULL);
}

static uint8_t *RealFrame(FILE *f, const Fr *fr, size_t *len)
{
    uint8_t *d = malloc((size_t)(fr->last - fr->first + 1) * 2016u);
    size_t n = 0;
    uint32_t lba;
    if (!d) return NULL;
    for (lba = fr->first; lba <= fr->last; lba++) {
        uint8_t raw[2352];
        if (!ReadSector(f, lba, raw)) { free(d); return NULL; }
        if (!(raw[18] & 8u) || raw[24] != 0x60 || raw[25] != 1 || raw[26] != 1 || raw[27] != 0x80) continue; /* interleaved non-video sector */
        memcpy(d + n, raw + 56, 2016u); n += 2016u;
    }
    *len = fr->size < n ? fr->size : n;
    return d;
}

/* ---- case frames ---- */
static uint8_t *UpdaterFrame(size_t *len)
{ /* the test_movie_updater.h record: 12 zero bytes, word 0x1234, 64 zero bytes (generator: bytes(0xC)+<H 0x1234>+bytes(0x40)) */
    uint8_t *d = calloc(1, 78);
    d[12] = 0x34; d[13] = 0x12;
    *len = 78;
    return d;
}

static const uint8_t *SynFrame(const char *name, size_t *len)
{
    unsigned k;
    for (k = 0; k < sizeof(MDECVLC_syn) / sizeof(MDECVLC_syn[0]); k++)
        if (!strcmp(MDECVLC_syn[k].name, name)) { *len = MDECVLC_syn[k].insize; return MDECVLC_syn[k].in; }
    return NULL;
}

/* known out-of-spec divergences: the original keeps decoding the unused all-zero AC prefix 000000000000 (it makes progress
 * and only hangs later, 'updater-scenario' = an all-zero bitstream); this decoder reports PE_VLC_ERR_DESYNC there (the
 * existing 'original-hang vectors' rule).  The dependent steps that follow (ours is dead: a negative return, where the original hangs) are counted separately. */
static int KnownDivergent(const char *name, uint32_t bound, unsigned step)
{ /* pinned to the four observed (bound, step) pairs of the all-zero 'updater-scenario' frame */
    return !strcmp(name, "updater-scenario") && ((step == 1 && (bound == 0 || bound == 1)) || (step == 0 && (bound == 3 || bound == 4)));
}

int main(void)
{
    static uint16_t hw[HWCAP], full[HWCAP];
    static uint8_t cat[2u * HWCAP + 4u];
    const char *disc = getenv("PE_DISC1_BIN");
    FILE *f = NULL;
    Fr *frs = NULL;
    unsigned need = 0, k, steps_ok = 0, steps_div = 0, steps_bad = 0, steps_skipped = 0, chains_eq = 0, chains_full = 0;
    unsigned steps_dep = 0, cases_run = 0, cases_skipped = 0, endword_ok = 0, endword_n = 0, resume_err = 0;
    size_t off = 0;

    for (k = 0; k < NCASES; k++)
        if (MDECVLCB_case[k].real_index && MDECVLCB_case[k].real_index > need) need = MDECVLCB_case[k].real_index;
    if (need && disc && (f = fopen(disc, "rb"))) {
        frs = ScanFrames(f, need);
        if (!frs) { fprintf(stderr, "disc scan found fewer than %u frames\n", need); return 2; }
    }

    for (k = 0; k < NCASES; k++) {
        const __typeof__(MDECVLCB_case[0]) *c = &MDECVLCB_case[k];
        const __typeof__(MDECVLCB_step[0]) *sv = &MDECVLCB_step[off];
        const char *name = c->name;
        uint8_t *own = NULL;
        const uint8_t *data = NULL;
        size_t n = 0, total_hw = 0, cat_len = 0, ref_len = 0;
        unsigned s, count = 0, div = 0;
        pe_vlc_decoder_t st;
        int chain_complete = 0, bad = 0;

        off += c->nsteps;
        if (c->real_index) {
            if (!frs) { cases_skipped++; steps_skipped += c->nsteps; continue; }
            own = RealFrame(f, &frs[c->real_index - 1], &n);
            data = own;
        } else if (!strcmp(name, "updater-scenario")) {
            own = UpdaterFrame(&n); data = own;
        } else if (!strncmp(name, "syn-", 4)) {
            data = SynFrame(name + 4, &n);
        }
        if (!data || n != c->size || Fnv(data, n, FNV0) != c->in_hash) {
            printf("BAD INPUT: case %s bound 0x%X: frame missing or input hash differs\n", name, (unsigned)c->bound);
            free(own); return 1;
        }
        cases_run++;
        count = data[0] | (data[1] << 8);
        cat[0] = data[0]; cat[1] = data[1]; cat[2] = data[2]; cat[3] = data[3]; cat_len = 4;
        for (s = 0; s < c->nsteps; s++) {
            size_t written = 0, bits = 0;
            uint64_t h = FNV0;
            uint32_t added, a0, a1;
            int rc, first = s == 0, ok = 1;
            if (first) {
                if (sv[s].resume || pe_vlc_decode_begin(&st, data, n) != 0) { printf("BAD: case %s begin\n", name); free(own); return 1; }
            } else if (!sv[s].resume) { printf("BAD: case %s step %u resume flag\n", name, s); free(own); return 1; }
            rc = pe_vlc_decode_step(&st, hw, HWCAP, c->bound, &written, &bits);
            if (sv[s].ret == 0xFFFFFFFFu) { /* original: no exit within budget */
                ok = rc < 0;
            } else {
                size_t i;
                added = (uint32_t)((first ? 4u : 0u) + 2u * written);
                if (first) { uint8_t hd[4]; memcpy(hd, data, 4); h = Fnv(hd, 4, h); }
                for (i = 0; i < written; i++) { uint8_t b2[2]; b2[0] = (uint8_t)hw[i]; b2[1] = (uint8_t)(hw[i] >> 8); h = Fnv(b2, 2, h); }
                total_hw += written;
                a1 = (uint32_t)(4u + 2u * total_hw);
                a0 = (uint32_t)(8u + 2u * ((bits + 7u + 15u) / 16u));
                ok = (uint32_t)rc == sv[s].ret && added == sv[s].added && h == sv[s].hash && a0 == sv[s].a0_rel && a1 == sv[s].a1_rel;
                { size_t j; for (j = 0; j < written; j++) { cat[cat_len + 2 * j] = (uint8_t)hw[j]; cat[cat_len + 2 * j + 1] = (uint8_t)(hw[j] >> 8); } cat_len += 2 * written; }
                if (rc == 0) { chain_complete = 1; endword_n++; if (sv[s].end_word_rel == 4u + 4u * count) endword_ok++; }
            }
            if (ok) { if (div) steps_dep++; else steps_ok++; continue; }
            if (KnownDivergent(name, c->bound, s)) { steps_div++; div = 1; continue; }
            steps_bad++; bad = 1;
            if (steps_bad <= 400)
                printf("MISMATCH: %s bound 0x%X step %u: ours ret %d +%u hw bits %u (a0 %u a1 %u) | original ret %u added %u a0 %u a1 %u\n",
                       name, (unsigned)c->bound, s, rc, (unsigned)written, (unsigned)bits,
                       (unsigned)(8u + 2u * ((bits + 7u + 15u) / 16u)), (unsigned)(4u + 2u * total_hw),
                       (unsigned)sv[s].ret, (unsigned)sv[s].added, (unsigned)sv[s].a0_rel, (unsigned)sv[s].a1_rel);
            break;
        }
        if (bad) steps_skipped += c->nsteps - s - 1u;
        /* a chain that ended with a complete frame equals the complete-frame decode of the same frame */
        if (!bad && chain_complete) {
            size_t rl = 0;
            int rc = pe_vlc_decode_frame_mdec(data, n, full, HWCAP, &rl);
            ref_len = rl * 2u;
            chains_full++;
            if (rc == 0 && ref_len == cat_len) {
                size_t j; int same = 1;
                for (j = 0; j < rl; j++) if (cat[2 * j] != (uint8_t)full[j] || cat[2 * j + 1] != (uint8_t)(full[j] >> 8)) { same = 0; break; }
                if (same) chains_eq++;
                else { printf("MISMATCH: %s bound 0x%X: concatenated chain differs from the complete-frame output\n", name, (unsigned)c->bound); steps_bad++; }
            } else { printf("MISMATCH: %s bound 0x%X: chain length %u != complete-frame %u\n", name, (unsigned)c->bound, (unsigned)cat_len, (unsigned)ref_len); steps_bad++; }
        }
        /* a step with nothing to resume must fail, not loop: after a completed chain */
        if (chain_complete) { size_t w2 = 0, b2 = 0; if (pe_vlc_decode_step(&st, hw, HWCAP, c->bound, &w2, &b2) == PE_VLC_ERR_STATE) resume_err++; else { printf("MISMATCH: %s: step after completion did not fail\n", name); steps_bad++; } }
        free(own);
    }
    if (f) fclose(f);
    free(frs);
    printf("cases run %u (skipped %u: no PE_DISC1_BIN), steps matched %u, known-divergent steps %u (+%u dependent), mismatched steps %u (+%u unreached), "
           "chains equal to complete-frame output %u/%u, resume-after-complete errors %u, end word (4+4*count) %u/%u\n",
           cases_run, cases_skipped, steps_ok, steps_div, steps_dep, steps_bad, steps_skipped, chains_eq, chains_full, resume_err, endword_ok, endword_n);
    if (steps_bad) { printf("FAIL\n"); return 1; }
    if (!cases_skipped && steps_div != 4) { printf("FAIL: %u known-divergent steps, expected exactly 4\n", steps_div); return 1; }
    if (cases_skipped) { printf("PARTIAL (set PE_DISC1_BIN for the real-frame chains)\n"); return 2; }
    printf("PASS: %u/%u steps explained (%u exact, %u known divergent, %u dependent on a divergence)\n", steps_ok + steps_div + steps_dep, (unsigned)NSTEPS, steps_ok, steps_div, steps_dep);
    return 0;
}
